const stop=JSON.parse(readFileSync(root+'openspec/changes/implement-scroll-driven-score-assembly-and-motion/stage-1-projects-interaction-clearance-stop-diagnostics.json','utf8'));
it('replays unmodified Professional constructors and derives only existing visit-2 constraints',()=>{
 const records=[];
 const extra=[];
 for(const [revision,build,buildGeometry] of [['current',current,currentGeometry],['stage0',stage0,stage0Geometry],['phase9',phase9,phase9Geometry]] as const){
  for(let index=0;index<3;index++){
   const fixture=measured[index],o=fixture.options,w=stop.occurrences[index];
   const branch=build('horizontal-enhanced','professional',o.viewportWidth,o.viewportHeight,o.sceneMeasurements);
   const geometry=buildGeometry('professional',o.viewportWidth,o.viewportHeight,o.sceneMeasurements,48);
   const zones=branch.zones.filter(z=>z.chapterId==='professional-projects' && z.kind==='notation-safe');
   const zone=zones[1]!,anchor=zone.projectVisit!.anchor,card=zone.projectVisit!.cardRect;
   const range=geometry.notationRanges.find(r=>r.projectVisit?.projectIndex===2)!;
   const ranges=geometry.notationRanges.filter(r=>r.chapterId==='professional-projects');
   const normalizedFocus={x:card.x-9,y:card.y-9,width:card.width+18,height:card.height+18};
   const edgeAt=(x:number)=>branch.model.staff.lines.flatMap(line=>line.points.slice(1).flatMap((b,i)=>{const a=line.points[i]!;return Math.min(a.x,b.x)<=x && x<=Math.max(a.x,b.x) && a.x!==b.x ? [{id:line.id,a,b,stroke:line.thickness,y:a.y+(b.y-a.y)*(x-a.x)/(b.x-a.x)}]:[]}));
   const targetEdges=edgeAt(anchor.x).filter(e=>e.y>card.y+card.height);
   const centerWitness=targetEdges.map(e=>({...e,gap:e.y-e.stroke/2-(card.y+card.height+9)})).sort((a,b)=>a.gap-b.gap)[0]!;
   expect(centerWitness.gap).toBeGreaterThan(0);expect(centerWitness.gap).toBeLessThan(12);
   const edges=branch.model.staff.lines.flatMap(line=>line.points.slice(1).map((b,i)=>({a:line.points[i]!,b,radius:line.thickness/2})));
   const minGap=Math.min(...edges.map(e=>projectsSegmentClearance(e.a,e.b,normalizedFocus,e.radius)));
   const samples=Array.from({length:65},(_,i)=>{const t=zone.startT+(zone.endT-zone.startT)*i/64;return branch.path.pointAt(t)});
   const localStart=zones[0]!.startT,localEnd=zones[2]!.endT;
   const local=Array.from({length:2049},(_,i)=>{const t=localStart+(localEnd-localStart)*i/2048;return {point:branch.path.pointAt(t),curvature:branch.path.curvatureAt(t)}});
   const maximumLocalCurvature=Math.max(...local.map(p=>Math.abs(p.curvature)));
   const clearanceFloor=w.outlineBottomCssPx+12+24+0.36;
   const cap=o.viewportHeight-7*12;
   // Existing geometry only; no hypothetical knot mutation or candidate repair.
   let low=zone.startT,high=zone.endT;
   for(let k=0;k<50;k++){const mid=(low+high)/2;if(branch.path.pointAt(mid).x<anchor.x)low=mid;else high=mid;}
   const segmentIndex=Math.floor((low+high)/2*branch.path.segmentCount);
   const rawCard=w.measurement.card,B=rawCard.y+rawCard.height,cx=rawCard.x+rawCard.width/2;
   const sweep={x:cx-1.025*(rawCard.width/2+9),y:B-24-1.025*(rawCard.height+9),width:2*1.025*(rawCard.width/2+9),height:(B+9)-(B-24-1.025*(rawCard.height+9))};
   const transformedEdges=edges.map(e=>({a:{x:e.a.x*w.witness.svgScreenToTrackMatrix[0]+w.witness.svgScreenToTrackMatrix[4],y:e.a.y*w.witness.svgScreenToTrackMatrix[3]+w.witness.svgScreenToTrackMatrix[5]},b:{x:e.b.x*w.witness.svgScreenToTrackMatrix[0]+w.witness.svgScreenToTrackMatrix[4],y:e.b.y*w.witness.svgScreenToTrackMatrix[3]+w.witness.svgScreenToTrackMatrix[5]},radius:e.radius*w.witness.svgScreenToTrackMatrix[0]}));
   const minSweep=Math.min(...transformedEdges.map(e=>projectsSegmentClearance(e.a,e.b,sweep,e.radius)));
   const crossCount=(points:readonly {x:number,y:number}[])=>{
    let count=0;const orient=(a:{x:number,y:number},b:{x:number,y:number},c:{x:number,y:number})=>(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);
    for(let i=0;i<points.length-1;i++)for(let j=i+2;j<points.length-1;j++){const a=points[i]!,b=points[i+1]!,c=points[j]!,d=points[j+1]!;if(Math.max(a.x,b.x)<Math.min(c.x,d.x)||Math.max(c.x,d.x)<Math.min(a.x,b.x)||Math.max(a.y,b.y)<Math.min(c.y,d.y)||Math.max(c.y,d.y)<Math.min(a.y,b.y))continue;if(orient(a,b,c)*orient(a,b,d)<-1e-7&&orient(c,d,a)*orient(c,d,b)<-1e-7)count++;}return count;
   };
   extra.push({revision,fixture:fixture.id,fullTransitionOuterBounds:sweep,minimumExistingStaffClearanceToConservativeSweepCssPx:minSweep,interiorWitnessSegment:segmentIndex,interiorWitnessKnotIndices:[segmentIndex-1,segmentIndex,segmentIndex+1,segmentIndex+2],interiorWitnessKnots:geometry.knots.slice(segmentIndex-1,segmentIndex+3),incomingConnectorEndsBeforeKnot:range.startSegmentIndex-1,outgoingConnectorStartsAfterKnot:range.endSegmentIndex+1,existingBranchIntersections:{center2049:crossCount(Array.from({length:2049},(_,i)=>branch.path.pointAt(i/2048))),staff1025:branch.model.staff.lines.map(l=>crossCount(l.points))},joinHorizontalRuns:[ranges[1]!.projectVisit!.anchor.x-ranges[0]!.projectVisit!.anchor.x,ranges[2]!.projectVisit!.anchor.x-ranges[1]!.projectVisit!.anchor.x],valleyY:Math.min(o.viewportHeight-36,Math.max(...ranges.map(r=>r.projectVisit!.anchor.y))+36)});
   records.push({revision,fixture:fixture.id,input:o,focusInputSource:'Saved DOM link inset 1px, observed outline width4+offset6; common normalized card frame reconstructed at focus start. Historical style source equality checked independently.',card,anchor,zone:{id:zone.id,startT:zone.startT,endT:zone.endT,semanticSlotIds:zone.semanticSlotIds,eventCount:zone.eventCount},range,shelfControlKnots:geometry.knots.slice(range.startSegmentIndex-1,range.endSegmentIndex+2),zoneSamples:samples,centerWitness,minimumClearanceAgainstNormalizedStartFocusEnvelope:minGap,staffCount:branch.model.staff.lines.length,eventPrimitives:branch.model.primitives.filter(p=>p.id.startsWith('wf-professional-projects:reserved:')),joins:ranges.map(r=>({visit:r.projectVisit?.projectIndex,start:r.startSegmentIndex,end:r.endSegmentIndex,anchor:r.projectVisit?.anchor,firstPoint:geometry.knots[r.startSegmentIndex-1],lastPoint:geometry.knots[r.endSegmentIndex+1]})),continuity:branch.path.continuity,maximumExistingLocalCurvature:maximumLocalCurvature,existingOuterOffsetCurvatureProduct:maximumLocalCurvature*24,minimumExistingLocalDeltaX:Math.min(...local.slice(1).map((v,i)=>v.point.x-local[i]!.point.x)),necessaryWitnessDownwardShift:12-centerWitness.gap,conservativeStraightShelfOnlyAnchorBand:{minimum:clearanceFloor,maximum:cap,slack:cap-clearanceFloor,meaning:'Analytic reservation band for full five-line ink below focus envelope; original height cap retained. NOT a repaired spline/connector/global acceptance interval or repair candidate.'}});
  }
 }
 for(let i=0;i<3;i++){
  const group=records.filter(r=>r.fixture===measured[i].id);
  expect(group[0]!.card).toEqual(group[1]!.card);expect(group[1]!.card).toEqual(group[2]!.card);
  // Stable local control geometry; global parameter/sample phase may differ after other Stage-1 repairs.
  expect(group[0]!.shelfControlKnots).toEqual(group[1]!.shelfControlKnots);expect(group[1]!.shelfControlKnots).toEqual(group[2]!.shelfControlKnots);
  expect(group.every(r=>r.zone.eventCount===0 && r.staffCount===5)).toBe(true);
 }
 writeFileSync('/tmp/wflyer-visit2-governance/constraint-results.json',JSON.stringify(extra,null,2)+'\n');
