 console.log(JSON.stringify(records.map(r=>({revision:r.revision,fixture:r.fixture,witness:r.centerWitness.gap,minimumStartFocusGap:r.minimumClearanceAgainstNormalizedStartFocusEnvelope,anchorBand:r.conservativeStraightShelfOnlyAnchorBand,curvature:r.maximumExistingLocalCurvature,eventCount:r.zone.eventCount})),null,2));
},30000);
